<template><section class="document-card"><header><span class="file-symbol">{{ pdf?'PDF':'DOC' }}</span><div><h3>{{ file.title || file.filename || '小易生成的文档' }}</h3><p>{{ file.filename }}<span v-if="file.fileSize"> · {{ formatSize(file.fileSize) }}</span></p></div></header><div class="document-buttons"><button :disabled="busy" @click="download">{{ busy?'读取文件…':'保存文件' }}</button><button v-if="pdf" @click="preview=!preview">{{ preview?'收起预览':'预览 PDF' }}</button><button v-if="previewError && preview" @click="loadPreview">重新加载</button></div><p v-if="notice" class="file-notice" role="status">{{ notice }}</p><div v-if="pdf&&preview" class="pdf-preview"><p v-if="!blobUrl">{{ previewError || '正在打开 PDF…' }}</p><iframe v-else :src="blobUrl" :title="(file.title||'文档')+' PDF预览'"></iframe><p class="preview-note">可在预览中查看和选择文字；浏览器不支持预览时，可点击“保存文件”。</p></div></section></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import request from '../api/index'
import {localDocumentUrl} from '../utils/assistantPresentation'
const props=defineProps({file:{type:Object,required:true}}),url=computed(()=>localDocumentUrl(props.file.downloadUrl,window.location.origin)),pdf=computed(()=>props.file.fileType==='pdf'||url.value.endsWith('.pdf'))
const preview=ref(pdf.value),blobUrl=ref(''),busy=ref(false),notice=ref(''),previewError=ref('');let pending,alive=true
function formatSize(n){return n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB'}
async function ensureBlob(){if(blobUrl.value)return blobUrl.value;if(pending)return pending;if(!url.value)throw Error('文件地址无效');pending=request.get(url.value+'?inline=true',{baseURL:'',responseType:'blob'}).then(async blob=>{if(!(blob instanceof Blob)||!blob.size)throw Error('文件内容为空，请重新生成');if(pdf.value && await blob.slice(0,5).text()!=='%PDF-')throw Error('返回的文件不是有效 PDF，请重新生成');if(!alive)return '';blobUrl.value=URL.createObjectURL(blob);return blobUrl.value}).finally(()=>{pending=null});return pending}
async function download(){if(busy.value)return;busy.value=true;notice.value='';try{const blob=await ensureBlob();if(!blob)return;const a=document.createElement('a');a.href=blob;a.download=props.file.filename||'小易文档.'+(pdf.value?'pdf':'docx');document.body.appendChild(a);try{a.click()}finally{a.remove()}notice.value='已交给浏览器保存，请查看下载记录。'}catch(e){notice.value=e.message||'下载失败，请重试'}finally{busy.value=false}}
async function loadPreview(){if(!pdf.value||!preview.value)return;previewError.value='';try{await ensureBlob()}catch(e){previewError.value='预览加载失败，可以重试或下载文件。'}}
watch(preview,loadPreview);onMounted(loadPreview);onBeforeUnmount(()=>{alive=false;if(blobUrl.value)URL.revokeObjectURL(blobUrl.value)})
</script>
<style scoped>
.document-card{border:1px solid #d9e1d7;border-radius:8px;background:#fffefa;margin:17px 0;padding:20px;max-width:850px}.document-card header{display:flex;align-items:center;gap:13px}.file-symbol{font-size:11px;letter-spacing:1px;background:#e5eee5;color:#16765f;padding:14px 8px;border-radius:4px;font-weight:700}.document-card h3{font-size:15px;line-height:1.7;margin:0}.document-card header p{font-size:10px;color:#899384;margin:5px 0;overflow-wrap:anywhere}.document-buttons{display:flex;gap:9px;flex-wrap:wrap;margin-top:15px}.document-buttons button{padding:8px 12px;border:1px solid #cbd9cc;background:#f4f7ef;color:#196b57;font-size:11px;border-radius:4px;cursor:pointer}.document-buttons button:first-child{background:#168b78;color:#fff;border-color:#168b78}.document-buttons button:disabled{opacity:.5}.pdf-preview{margin-top:15px}.pdf-preview iframe{width:100%;height:500px;border:1px solid #d9e1d7;border-radius:4px;background:#eee}.pdf-preview>p,.file-notice{font-size:11px;color:#6a7b6a;line-height:1.8;margin:8px 0}.document-text{font:inherit;font-size:13px;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere;max-height:500px;overflow:auto;background:#f7f8f1;padding:18px;margin-top:16px;border-radius:5px;user-select:text}@media(max-width:700px){.document-card{padding:15px}.pdf-preview iframe{height:380px}}
</style>
